/* ===================== BÀI 50 · Máy trạng thái hữu hạn ===================== */
/* Bài 50 · Máy trạng thái hữu hạn (AMTS-EMB-001-M13-L02, MC51-050) — sinh bởi tools/author/mcu8051/l50.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P50=[{"label":"Ví dụ: Công tắc bật/tắt là máy 2 trạng thái","code":"; Ví dụ 1: công tắc bật/tắt là máy 2 trạng thái\n; Sự kiện lấy từ bảng kịch bản EV: 1 = nhấn nút, 0 = không\nSTATE   DATA    30H                     ; 0 = TẮT, 1 = BẬT\nEVT     DATA    31H                     ; sự kiện của bước này\nNTR     DATA    32H                     ; số lần chuyển trạng thái\n        ORG     0000H\n        MOV     R7,#0                   ; vị trí trong kịch bản\nBUOC:   MOV     A,R7\n        MOV     DPTR,#EV\n        MOVC    A,@A+DPTR               ; đọc sự kiện kế tiếp\n        CJNE    A,#0FFH,CO              ; FFH = hết kịch bản\n        SJMP    XONG\nCO:     MOV     EVT,A\n        INC     R7\n        MOV     A,STATE\n        JNZ     S_BAT\nS_TAT:  MOV     A,EVT                   ; trạng thái TẮT\n        CJNE    A,#1,BUOC               ; chỉ sự kiện NHẤN làm chuyển\n        MOV     STATE,#1                ; chuyển sang BẬT\n        CLR     P1.0                    ; action: bật LED\n        INC     NTR\n        SJMP    BUOC\nS_BAT:  MOV     A,EVT                   ; trạng thái BẬT\n        CJNE    A,#1,BUOC\n        MOV     STATE,#0                ; chuyển sang TẮT\n        SETB    P1.0                    ; action: tắt LED\n        INC     NTR\n        SJMP    BUOC\nXONG:   SJMP    $\nEV:     DB      0,1,0,0,1,1,0,0FFH\n        END\n","note":"Bấm Từng bước và xem Sơ đồ trạng thái: sự kiện 1 (NHẤN) ở bước 2, 5, 6 làm máy đổi TẮT ↔ BẬT; sự kiện 0 không làm gì. Đoán trước: sau kịch bản 0,1,0,0,1,1,0 máy ở trạng thái nào? (BẬT, NTR = 3, LED P1.0 sáng.)","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["TẮT","BẬT"],"edges":[[0,1,"NHẤN / bật LED"],[1,0,"NHẤN / tắt LED"]],"vars":[["EVT",49,"dec"],["NTR",50,"dec"],["R7 (bước)",7,"dec"]],"hint":"Bấm Từng bước: trạng thái hiện tại tô đậm, cạnh vừa đi qua có dấu ▶. Sự kiện 0 không làm đổi trạng thái."}},{"label":"Ví dụ: Đèn giao thông là máy Moore theo tick","code":"; Ví dụ 2: đèn giao thông = máy Moore chạy theo tick\n; ĐỎ 6 tick -> XANH 5 tick -> VÀNG 2 tick -> ĐỎ ...\n; LED: P1.0 đỏ, P1.1 vàng, P1.2 xanh (sáng khi chân = 0)\nTICK    DATA    30H\nLAST    DATA    31H\nSTATE   DATA    32H                     ; 0 = ĐỎ, 1 = XANH, 2 = VÀNG\nCNT     DATA    33H                     ; số tick còn lại của trạng thái\nNTR     DATA    34H\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     TICK\n        RETI\n        ORG     0030H\nMAIN:   MOV     CNT,#6                  ; bắt đầu ở ĐỎ, 6 tick\n        MOV     P1,#0FEH                ; output của ĐỎ\n        MOV     TMOD,#02H               ; tick 250 µs\n        MOV     TH0,#06H\n        MOV     TL0,#06H\n        SETB    ET0\n        SETB    EA\n        SETB    TR0\nVONG:   MOV     A,TICK\n        CJNE    A,LAST,MOI\n        SJMP    VONG\nMOI:    INC     LAST\n        DJNZ    CNT,KT                  ; chưa hết thời gian: giữ\n        INC     STATE                   ; sự kiện \"hết giờ\": sang kế\n        MOV     A,STATE\n        CJNE    A,#3,NAP\n        CLR     A\n        MOV     STATE,A                 ; sau VÀNG là ĐỎ\nNAP:    MOV     DPTR,#DUR               ; entry: nạp thời gian mới\n        MOVC    A,@A+DPTR\n        MOV     CNT,A\n        MOV     A,STATE\n        MOV     DPTR,#OUTP              ; output của trạng thái mới\n        MOVC    A,@A+DPTR\n        MOV     P1,A\n        INC     NTR\nKT:     MOV     A,LAST\n        CJNE    A,#22,VONG              ; chạy 22 tick rồi dừng\n        CLR     EA\n        CLR     TR0\n        SJMP    $\nDUR:    DB      6,5,2                   ; số tick của ĐỎ, XANH, VÀNG\nOUTP:   DB      0FEH,0FBH,0FDH\n        END\n","note":"Trạng thái sáng đổi ĐỎ → XANH → VÀNG → ĐỎ → XANH theo tick; LED P1.0 (đỏ), P1.2 (xanh), P1.1 (vàng) là output tra bảng OUTP khi vào trạng thái. Sau 22 tick: XANH, còn 2 tick, đã chuyển 4 lần.","dev":{"led":true},"fosc":12000000,"speed":"real","watch":{"title":"Sơ đồ trạng thái","state":50,"states":["ĐỎ","XANH","VÀNG"],"edges":[[0,1,"hết 6 tick"],[1,2,"hết 5 tick"],[2,0,"hết 2 tick"]],"vars":[["CNT",51,"dec"],["TICK",48,"dec"],["NTR",52,"dec"]],"hint":"Chạy ở tốc độ Thời gian thực hoặc Từ từ: trạng thái sáng đổi theo tick, LED P1.0/P1.2/P1.1 là output của trạng thái (máy Moore)."}},{"label":"Ví dụ: Cấp phôi phân nhánh bằng bảng nhảy","code":"; Ví dụ 3: chu trình cấp phôi, phân nhánh bằng bảng nhảy\n; Đầu vào mỗi bước (kịch bản IN): bit0 START, bit1 S_CUOI,\n; bit2 S_DAU (xi lanh ở đầu), bit3 CO_PHOI\n; Van: P1.0 đẩy, P1.1 lùi (mức 0 = bật)\nSTATE   DATA    30H                     ; 0 CHỜ, 1 ĐẨY, 2 LÙI\nINP     DATA    31H\nDEM     DATA    32H                     ; số phôi đã cấp\n        ORG     0000H\n        MOV     R7,#0\nBUOC:   MOV     A,R7\n        MOV     DPTR,#IN\n        MOVC    A,@A+DPTR               ; \"đọc cảm biến\" của bước này\n        CJNE    A,#0FFH,CO\n        SJMP    XONG\nCO:     MOV     INP,A\n        INC     R7\n        MOV     A,STATE\n        RL      A                       ; mỗi mục AJMP dài 2 byte\n        MOV     DPTR,#BANG\n        JMP     @A+DPTR\nBANG:   AJMP    S_CHO\n        AJMP    S_DAY\n        AJMP    S_LUI\nS_CHO:  MOV     A,INP                   ; guard: START và CO_PHOI\n        ANL     A,#09H\n        CJNE    A,#09H,BUOC\n        MOV     STATE,#1\n        CLR     P1.0                    ; action: mở van đẩy\n        SJMP    BUOC\nS_DAY:  MOV     A,INP                   ; chờ S_CUOI\n        JNB     ACC.1,BUOC\n        MOV     STATE,#2\n        SETB    P1.0                    ; đóng van đẩy\n        CLR     P1.1                    ; mở van lùi\n        SJMP    BUOC\nS_LUI:  MOV     A,INP                   ; chờ S_DAU\n        JNB     ACC.2,BUOC\n        MOV     STATE,#0\n        SETB    P1.1\n        INC     DEM                     ; xong một phôi\n        SJMP    BUOC\nXONG:   SJMP    $\nIN:     DB      04H,05H,0DH,08H,0AH,00H,04H\n        DB      0DH,0AH,04H,0FFH\n        END\n","note":"Kịch bản đầu vào IN: bước 2 có START nhưng không có phôi nên guard chặn; bước 3 đủ điều kiện, van đẩy P1.0 bật. Hai chu trình xong: DEM = 2, máy về CHỜ, mọi van tắt. Mỗi lần phân nhánh qua bảng nhảy tốn đúng 8 chu kỳ.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI"],"edges":[[0,1,"START và CO_PHOI / mở van đẩy"],[1,2,"S_CUOI / đóng đẩy, mở lùi"],[2,0,"S_DAU / đóng lùi, DEM + 1"]],"vars":[["INP",49,"hex"],["DEM",50,"dec"],["R7 (bước)",7,"dec"]],"hint":"Bước 2 có START nhưng chưa có phôi (INP = 05H): guard sai nên giữ CHỜ. Theo dõi van P1.0 (đẩy), P1.1 (lùi)."}},{"label":"Lỗi: Trạng thái ngoài bảng nhảy","code":"; Lỗi: STATE bị ghi sai thành 5, bảng nhảy chỉ có 3 mục\nSTATE   DATA    30H\n        ORG     0000H\n        MOV     STATE,#5                ; giả lập: một lỗi khác ghi nhầm\n        MOV     A,STATE\n        RL      A                       ; mỗi mục AJMP dài 2 byte\n        MOV     DPTR,#BANG\n        JMP     @A+DPTR                 ; 5 x 2 = 10: ra ngoài bảng!\nS_CHO:  MOV     P1,#0FFH                ; tắt mọi van\n        SJMP    XONG\nS_DAY:  MOV     P1,#0FEH                ; van đẩy\n        SJMP    XONG\nS_LUI:  MOV     P1,#0FDH                ; van lùi\nXONG:   SJMP    $\nBANG:   AJMP    S_CHO\n        AJMP    S_DAY\n        AJMP    S_LUI\n        END\n","note":"STATE = 5 nhưng bảng chỉ có 3 mục: RL A cho 10, JMP @A+DPTR nhảy tới 0019H + 0AH = 0023H, chỗ không có lệnh. Trình mô phỏng dừng và báo lỗi ở PC = 0023H; chip thật sẽ chạy tiếp bất cứ byte nào ở đó.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI"],"vars":[["A (chỉ số)",224,"hex"]],"sfr":true,"hint":"STATE = 5 không có trong bảng: JMP @A+DPTR nhảy tới BANG + 10 = 0023H, chỗ không có lệnh."}},{"label":"Bẫy: Quên xóa cờ sự kiện","code":"; Bẫy: xử lý sự kiện nhưng quên xóa cờ sự kiện\n; Một lần nhấn phải đảo trạng thái đúng một lần\nSTATE   DATA    30H                     ; 0 = TẮT, 1 = BẬT\nNTR     DATA    32H\nEVF     BIT     20H.0                   ; cờ \"có lần nhấn\" (ISR nút bật)\n        ORG     0000H\n        SETB    EVF                     ; giả lập: ISR nút bật cờ 1 lần\n        MOV     R6,#4                   ; máy trạng thái chạy 4 bước\nBUOC:   JNB     EVF,TIEP                ; không có sự kiện: bỏ qua\n                                        ; THIẾU: CLR EVF (tiêu thụ sự kiện)\n        MOV     A,STATE\n        XRL     A,#1                    ; đảo trạng thái\n        MOV     STATE,A\n        CPL     P1.0                    ; action đi kèm\n        INC     NTR\nTIEP:   DJNZ    R6,BUOC\n        SJMP    $                       ; mong: STATE = 1, NTR = 1\n        END\n","note":"Cờ EVF chỉ được bật một lần nhưng không bao giờ bị xóa: cả 4 bước đều thấy “có sự kiện”, trạng thái đảo 4 lần và quay về TẮT, NTR = 4 thay vì 1. Sửa: thay JNB EVF,TIEP bằng JBC EVF,XU_LY (kiểm và xóa trong một lệnh).","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["TẮT","BẬT"],"edges":[[0,1,"có cờ EVF"],[1,0,"có cờ EVF"]],"vars":[["EVF (20H.0)","20H.0","bit"],["NTR",50,"dec"],["R6",6,"dec"]],"hint":"EVF không bao giờ về 0 nên mỗi bước máy lại thấy “có sự kiện”: trạng thái đảo 4 lần."}},{"label":"Sửa: Kiểm phạm vi STATE trước khi nhảy","code":"; Sửa: kiểm phạm vi STATE trước khi nhảy theo bảng\nSTATE   DATA    30H                     ; 0 CHỜ, 1 ĐẨY, 2 LÙI, 3 LỖI\nERR     DATA    31H                     ; giá trị STATE hỏng đã gặp\n        ORG     0000H\n        MOV     STATE,#5                ; cùng lỗi như ví dụ 4\n        MOV     A,STATE\n        CJNE    A,#3,$+3                ; CY = 1 khi STATE < 3\n        JNC     S_LOI                   ; ngoài bảng: vào trạng thái lỗi\n        RL      A\n        MOV     DPTR,#BANG\n        JMP     @A+DPTR\nS_LOI:  MOV     P1,#7FH                 ; tắt van, bật đèn lỗi P1.7\n        MOV     ERR,A                   ; ghi lại giá trị hỏng để chẩn đoán\n        MOV     STATE,#3                ; vào trạng thái LỖI (có định nghĩa)\n        SJMP    XONG\nS_CHO:  MOV     P1,#0FFH\n        SJMP    XONG\nS_DAY:  MOV     P1,#0FEH\n        SJMP    XONG\nS_LUI:  MOV     P1,#0FDH\nXONG:   SJMP    $\nBANG:   AJMP    S_CHO\n        AJMP    S_DAY\n        AJMP    S_LUI\n        END\n","note":"Cùng STATE = 5, nhưng CJNE A,#3,$+3 / JNC chặn trước bảng nhảy: máy vào trạng thái LỖI (STATE = 3, có định nghĩa), tắt mọi van, bật đèn lỗi P1.7 (P1 = 7FH) và ghi giá trị hỏng ERR = 05H để chẩn đoán. Bài 51 phát triển trạng thái này thành lỗi có phục hồi.","dev":{"led":true},"fosc":12000000,"watch":{"title":"Sơ đồ trạng thái","state":48,"states":["CHỜ","ĐẨY","LÙI","LỖI"],"vars":[["ERR",49,"hex"]],"hint":"STATE = 5 bị chặn trước bảng nhảy: chương trình vào trạng thái LỖI (3), tắt van, bật đèn lỗi P1.7 và ghi giá trị hỏng vào ERR."}}];
const sim50=makeSim51(document.getElementById("m51-l50"),{id:"s50",presets:P50,ram:256});
makeEx51(document.getElementById("ex-l50"),"l50",[{"t":"Máy trạng thái của cửa","d":"<p>Cửa có 3 trạng thái: 0 ĐÓNG, 1 MỞ, 2 KHÓA (ô <code>30H<\/code>). Sự kiện ở ô <code>31H<\/code>: 1 MO, 2 DONG, 3 KHOA, 4 MO_KHOA. Chỉ có 4 chuyển trạng thái: ĐÓNG + MO → MỞ; MỞ + DONG → ĐÓNG; ĐÓNG + KHOA → KHÓA; KHÓA + MO_KHOA → ĐÓNG. Mọi cặp khác (kể cả sự kiện không hợp lệ) giữ nguyên trạng thái. Ghi trạng thái mới vào <code>30H<\/code> và <code>32H<\/code> = <code>01H<\/code> nếu trạng thái đổi, <code>00H<\/code> nếu không. Ô <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 00H<\/code>, <code>31H = 01H<\/code> → <code>30H = 01H<\/code>, <code>32H = 01H<\/code>.<\/p>","start":"; Máy trạng thái của cửa: 30H = trạng thái, 31H = sự kiện\n; 0 ĐÓNG, 1 MỞ, 2 KHÓA · sự kiện 1 MO, 2 DONG, 3 KHOA, 4 MO_KHOA\n        ORG     0000H\n        MOV     32H,#00H                ; 32H = 01H nếu trạng thái đổi\n        MOV     A,30H\n        CJNE    A,#0,XONG               ; mới viết cho trạng thái ĐÓNG\n        MOV     A,31H\n        CJNE    A,#1,XONG\n        MOV     30H,#1                  ; ĐÓNG + MO -> MỞ\n        MOV     32H,#01H\n; viết tiếp: ĐÓNG + KHOA, MỞ + DONG, KHÓA + MO_KHOA\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":90}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":1}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":90}},"expect":{"iram":{"0x30":0,"0x31":2,"0x32":1}}},{"setup":{"iram":{"0x30":0,"0x31":3,"0x32":90}},"expect":{"iram":{"0x30":2,"0x31":3,"0x32":1}}},{"setup":{"iram":{"0x30":2,"0x31":4,"0x32":90}},"expect":{"iram":{"0x30":0,"0x31":4,"0x32":1}}},{"setup":{"iram":{"0x30":2,"0x31":1,"0x32":90}},"expect":{"iram":{"0x30":2,"0x31":1,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":3,"0x32":90}},"expect":{"iram":{"0x30":1,"0x31":3,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":90}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":90}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0}}}]},"hints":["Vẽ sơ đồ 3 vòng tròn và 4 mũi tên trước khi viết code; mọi sự kiện không có mũi tên thì không làm gì.","Rẽ nhánh theo trạng thái trước (CJNE A,#0…; CJNE A,#1…), trong từng nhánh mới xét sự kiện. Đặt 32H = 00H ngay đầu chương trình.","Mỗi chuyển hợp lệ: ghi trạng thái mới vào 30H rồi nhảy tới một nhãn chung ghi 32H = 01H; các nhánh không chuyển nhảy thẳng tới SJMP $."],"why":"Máy trạng thái chỉ đổi khi có đúng cặp (trạng thái, sự kiện) trên sơ đồ; mọi cặp khác là “giữ nguyên”. Bộ thử 5 (KHÓA + MO) là guard của bài toán: cửa khóa không mở được bằng lệnh MO; bộ thử 7 kiểm sự kiện không hợp lệ."},{"t":"Một bước đèn giao thông","d":"<p>Đèn có <code>30H<\/code> = STATE (0 ĐỎ, 1 XANH, 2 VÀNG), <code>31H<\/code> = CNT (số tick còn lại, ≥ 1), <code>32H<\/code> = REQ (≠ 0: người đi bộ đã bấm nút). Viết <b>một bước<\/b> (chạy mỗi tick) theo đúng thứ tự: (1) guard: nếu STATE = XANH và REQ ≠ 0 thì xóa REQ = 0, và nếu CNT &gt; 2 thì đặt CNT = 2 (rút ngắn đèn xanh); ở trạng thái khác REQ giữ nguyên; (2) CNT giảm 1, nếu về 0 thì sang trạng thái kế (ĐỎ → XANH → VÀNG → ĐỎ) và nạp CNT = 6, 5, 2 tick theo trạng thái mới; (3) ghi ra <code>P1<\/code> mẫu đèn của trạng thái hiện tại: ĐỎ <code>FEH<\/code>, XANH <code>FBH<\/code>, VÀNG <code>FDH<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: STATE = 0, CNT = 4, REQ = 0 → STATE = 0, CNT = 3, P1 = FEH.<\/p>","start":"; Một bước đèn giao thông: 30H STATE, 31H CNT, 32H REQ\n        ORG     0000H\n; TODO: guard nút người đi bộ (chỉ ở XANH)\n        DJNZ    31H,RA                  ; hết thời gian chưa?\n        INC     30H                     ; sang trạng thái kế\n        MOV     31H,#6                  ; (sai: mọi trạng thái đều 6 tick)\nRA:     MOV     A,30H                   ; output Moore của trạng thái\n        MOV     DPTR,#OUTP\n        MOVC    A,@A+DPTR\n        MOV     P1,A\n        SJMP    $\nOUTP:   DB      0FEH,0FBH,0FDH,0FFH\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":4,"0x32":0}},"expect":{"iram":{"0x30":0,"0x31":3,"0x32":0},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":0}},"expect":{"iram":{"0x30":1,"0x31":5,"0x32":0},"ports":{"P1":251}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":0}},"expect":{"iram":{"0x30":2,"0x31":2,"0x32":0},"ports":{"P1":253}}},{"setup":{"iram":{"0x30":2,"0x31":1,"0x32":0}},"expect":{"iram":{"0x30":0,"0x31":6,"0x32":0},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":1,"0x31":5,"0x32":1}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0},"ports":{"P1":251}}},{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":1}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0},"ports":{"P1":251}}},{"setup":{"iram":{"0x30":0,"0x31":3,"0x32":1}},"expect":{"iram":{"0x30":0,"0x31":2,"0x32":1},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":1,"0x31":3,"0x32":1}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0},"ports":{"P1":251}}}]},"hints":["Code mẫu nạp 6 tick cho mọi trạng thái và không quay từ VÀNG về ĐỎ. Dùng bảng DB 6,5,2 với MOVC A,@A+DPTR, như ví dụ 2.","Guard: CJNE A,#1 để chỉ xét ở XANH; JZ khi REQ = 0. So CNT với 3 bằng CJNE A,#3,$+3 rồi JC (CY = 1 khi CNT &lt; 3).","Máy Moore: đầu ra tính theo trạng thái SAU bước, cho mọi nhánh (kể cả nhánh không chuyển)."],"why":"Bước guard → đếm → output tách ba phần của máy trạng thái: điều kiện (guard) chỉ có hiệu lực ở đúng trạng thái, sự kiện “hết giờ” sinh từ bộ đếm, output chỉ phụ thuộc trạng thái (Moore). Bộ thử 7 bắt lỗi xóa REQ ở trạng thái ĐỎ: yêu cầu bị mất trước khi đèn xanh tới."},{"t":"Bảng chuyển trạng thái gọn","d":"<p>Máy cấp phôi: <code>30H<\/code> = STATE (0 CHỜ, 1 ĐẨY, 2 LÙI, 3 LỖI), <code>31H<\/code> = EVENT (0 không có, 1 START, 2 S_CUOI, 3 S_DAU). Chuyển trạng thái: CHỜ + START → ĐẨY, CHỜ + S_CUOI → LỖI (cảm biến cuối báo khi chưa đẩy); ĐẨY + S_CUOI → LÙI; LÙI + S_DAU → CHỜ; LỖI giữ LỖI với mọi sự kiện; mọi cặp khác giữ nguyên. Code mẫu dùng chuỗi CJNE, vừa dài vừa sai. Viết lại để <code>30H<\/code> = trạng thái mới (31H giữ nguyên) với chỉ tiêu: không quá <b>11 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và không quá <b>30 byte<\/b> (tính cả bảng hằng).<\/p><p>Ví dụ: STATE = 0, EVENT = 1 → <code>30H = 01H<\/code>.<\/p>","start":"; Bảng chuyển trạng thái cấp phôi (code mẫu: chuỗi CJNE)\n; 30H STATE: 0 CHỜ 1 ĐẨY 2 LÙI 3 LỖI · 31H EVENT: 0..3\n        ORG     0000H\n        MOV     A,30H\n        CJNE    A,#0,K1\n        MOV     A,31H                   ; CHỜ\n        CJNE    A,#1,C2\n        MOV     30H,#1\nC2:     CJNE    A,#2,XONG\n        MOV     30H,#3\n        SJMP    XONG\nK1:     CJNE    A,#1,K2\n        MOV     A,31H                   ; ĐẨY\n        CJNE    A,#2,XONG\n        MOV     30H,#2\n        SJMP    XONG\nK2:     CJNE    A,#2,XONG\n        MOV     A,31H                   ; LÙI\n        CJNE    A,#3,XONG\n        MOV     30H,#1                  ; (sai đích)\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0,"0x31":1}},"expect":{"iram":{"0x30":1,"0x31":1}}},{"setup":{"iram":{"0x30":0,"0x31":2}},"expect":{"iram":{"0x30":3,"0x31":2}}},{"setup":{"iram":{"0x30":1,"0x31":2}},"expect":{"iram":{"0x30":2,"0x31":2}}},{"setup":{"iram":{"0x30":2,"0x31":3}},"expect":{"iram":{"0x30":0,"0x31":3}}},{"setup":{"iram":{"0x30":3,"0x31":1}},"expect":{"iram":{"0x30":3,"0x31":1}}},{"setup":{"iram":{"0x30":1,"0x31":0}},"expect":{"iram":{"0x30":1,"0x31":0}}},{"setup":{"iram":{"0x30":2,"0x31":1}},"expect":{"iram":{"0x30":2,"0x31":1}}},{"setup":{"iram":{"0x30":0,"0x31":3}},"expect":{"iram":{"0x30":0,"0x31":3}}}],"maxCyc":11,"maxBytes":30},"hints":["Chạy code mẫu với bộ thử 4 (LÙI + S_DAU): trạng thái mới sai. Chuỗi CJNE càng dài càng khó kiểm.","4 trạng thái × 4 sự kiện = 16 ô: lập bảng 16 byte, chỉ số = STATE × 4 + EVENT (RL A hai lần rồi ORL A,31H).","Đọc bảng bằng MOVC; dùng dạng @A+PC thì phải cộng thêm khoảng cách tới bảng. Không cần lệnh nhảy nào."],"why":"Máy trạng thái dạng bảng: mọi cặp (trạng thái, sự kiện) đều có một ô, nên không bỏ sót trường hợp và thời gian chạy không đổi (10–11 chu kỳ) dù máy có bao nhiêu chuyển. Đổi hành vi chỉ cần sửa bảng. Đổi lại, bảng tốn 16 byte ROM và EVENT phải được kiểm phạm vi trước khi tra (ở đây đề bảo đảm 0…3)."}]);

/* Bảng “Sơ đồ trạng thái” của Chương 13 (sinh bởi tools/author/mcu8051/m13lib.py): đọc RAM của máy giả lập, không đổi trình mô phỏng. */
(function(){const R=document.getElementById("m51-l50"),PS=P50,H2=v=>v.toString(16).toUpperCase().padStart(2,"0");let pi=-1,sec=null,last=null,prevS=null,edge=-1,seen=null;
 function rd(m,a){if(typeof a==="string"){const x=/^([0-9A-F]+)H\.([0-7])$/i.exec(a);return x?(m.iram[parseInt(x[1],16)]>>+x[2])&1:0}return a>=0x80&&a<0x100&&PS[pi].watch.sfr?m.sfr[a-0x80]:m.iram[a]}
 function shape(w){if(!sec){sec=document.createElement("section");sec.className="pn m13-w";sec.innerHTML='<div class="pane-h"><span>Sơ đồ trạng thái</span><span class="m13-h"></span></div><div class="m51-sec m13-b"></div>';}
  const sc=R.querySelector(".st-scroll");if(sec.parentNode!==sc)sc.insertBefore(sec,sc.firstChild);sec.hidden=!w;if(!w)return;
  sec.querySelector(".pane-h span").textContent=w.title||"Sơ đồ trạng thái";
  let h="";if(w.states)h+='<div class="m13-st" role="list" aria-label="Các trạng thái">'+w.states.map((s,i)=>'<span class="s" role="listitem" data-s="'+i+'">'+s+'</span>').join("")+'</div>';
  if(w.edges)h+='<ul class="m13-ed">'+w.edges.map((e,i)=>'<li data-e="'+i+'">'+w.states[e[0]]+' → '+w.states[e[1]]+': '+e[2]+'</li>').join("")+'</ul>';
  if(w.vars)h+='<div class="m13-vr">'+w.vars.map((v,i)=>'<span data-v="'+i+'"><b>'+v[0]+'</b> <i>–</i></span>').join("")+'</div>';
  h+='<p class="m13-hint">'+(w.hint||"Trạng thái và biến đọc từ RAM trong sau mỗi lệnh; ô vừa đổi được tô màu.")+'</p>';
  sec.querySelector(".m13-b").innerHTML=h;last=null;prevS=null;edge=-1;seen=null}
 function paint(m){const w=PS[pi].watch;if(!w)return;const H=sec.querySelector(".m13-h");
  if(!m){H.textContent="chưa chạy";sec.querySelectorAll(".m13-st .s").forEach(x=>x.classList.remove("on","was"));sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.remove("on"));sec.querySelectorAll(".m13-vr i").forEach(x=>x.textContent="–");last=null;prevS=null;edge=-1;return}
  if(m!==seen){seen=m;last=null;prevS=null;edge=-1}
  const vals=(w.vars||[]).map(v=>rd(m,v[1]));
  if(w.states){const s=rd(m,w.state);if(prevS!=null&&s!==prevS&&w.edges){const k=w.edges.findIndex(e=>e[0]===prevS&&e[1]===s);if(k>=0)edge=k}
   sec.querySelectorAll(".m13-st .s").forEach(x=>{x.classList.toggle("on",+x.dataset.s===s);x.classList.toggle("was",prevS!=null&&+x.dataset.s===prevS&&s!==prevS)});
   sec.querySelectorAll(".m13-ed li").forEach(x=>x.classList.toggle("on",+x.dataset.e===edge));
   H.textContent=s<w.states.length?"trạng thái "+s+" · "+w.states[s].replace(/<[^>]+>/g,""):"trạng thái "+H2(s)+"H (ngoài bảng!)";if(s!==prevS)prevS=s}
  else H.textContent="t = "+(m.cyc*12/m.fosc*1000).toLocaleString("vi-VN",{maximumFractionDigits:3})+" ms";
  sec.querySelectorAll(".m13-vr span").forEach((x,i)=>{const v=vals[i],k=w.vars[i][2]||"hex";x.querySelector("i").textContent=k==="dec"?String(v):k==="bit"?String(v):H2(v)+"H ("+v+")";x.classList.toggle("chg",!!last&&last[i]!==v)});last=vals}
 function loop(){const sc=R&&R.querySelector(".st-scroll");if(sc){const sel=R.querySelector(".s-pre"),i=sel?+sel.value:0;
   if(i!==pi){pi=i;const p=PS[i]||{};const sp=R.querySelector(".m51-sp");if(sp&&p.speed)sp.value=p.speed;shape(p.watch);sec&&(seen=null)}
   else if(sec&&sec.parentNode!==sc)shape(PS[pi].watch);
   if(PS[pi]&&PS[pi].watch){let m=null;try{m=sim50.machine()}catch(e){}paint(m)}}
  setTimeout(loop,150)}
 if(R)loop()})();

makeQuiz("quiz50","score50",[{"q": "Đèn giao thông: đèn đỏ sáng suốt thời gian ở trạng thái ĐỎ, chỉ phụ thuộc trạng thái hiện tại. Kiểu output này là gì?", "o": ["Output kiểu Mealy", "Guard của chuyển ĐỎ → XANH", "Output kiểu Moore", "Sự kiện hết giờ"], "a": 2, "e": "Moore: output là hàm của trạng thái. Mealy: output gắn với chuyển (chạy khi chuyển xảy ra), ví dụ “đếm phôi” khi LÙI → CHỜ."}, {"q": "Bảng nhảy gồm các lệnh AJMP. Vì sao có RL A trước JMP @A+DPTR?", "o": ["Mỗi mục AJMP dài 2 byte nên chỉ số phải nhân 2", "Để xóa cờ CY trước khi nhảy", "Vì JMP @A+DPTR chỉ nhận số chẵn", "Để chuyển STATE sang mã ASCII"], "a": 0, "e": "RL A dịch trái 1 bit = nhân 2 (khi STATE < 128). Bảng LJMP (3 byte) phải nhân 3. JMP @A+DPTR nhận mọi giá trị A."}, {"q": "Máy có 3 trạng thái, bảng nhảy 3 mục AJMP, nhưng một lỗi ghi STATE = 5. Trên AT89S52 thật, JMP @A+DPTR sẽ làm gì?", "o": ["CPU tự phát hiện và reset", "Nhảy tới BANG + 10 và chạy bất cứ byte nào ở đó như lệnh", "Nhảy về mục cuối của bảng", "Bỏ qua lệnh nhảy và chạy lệnh kế tiếp"], "a": 1, "e": "CPU không biết kích thước bảng; địa chỉ đích = DPTR + A = BANG + 10. Phải kiểm phạm vi STATE trước khi nhảy và đưa máy về trạng thái lỗi an toàn."}, {"q": "Ở trạng thái CHỜ, sự kiện START đến nhưng máng chưa có phôi (CO_PHOI = 0). Máy nên làm gì?", "o": ["Sang ĐẨY rồi chờ phôi trong trạng thái ĐẨY", "Sang LỖI vì START không hợp lệ", "Ghi nhớ START và tự sang ĐẨY khi phôi đến, kể cả sau vài giờ", "Giữ CHỜ, không mở van: guard của chuyển CHỜ → ĐẨY sai"], "a": 3, "e": "Guard là điều kiện phải đúng tại thời điểm sự kiện xảy ra; sai thì chuyển không xảy ra và action không chạy. Tự chạy sau vài giờ là hành vi nguy hiểm, không có trong yêu cầu."}, {"q": "ISR bật cờ EVF khi nhấn nút. Máy trạng thái dùng JNB EVF,BO_QUA rồi xử lý nhưng không xóa EVF. Hậu quả?", "o": ["Mỗi bước sau máy lại coi như có lần nhấn mới và chuyển tiếp", "Máy không bao giờ chuyển trạng thái", "ISR không bật được cờ lần sau nên bị mất ngắt", "Không sao, cờ tự xóa khi RETI"], "a": 0, "e": "Sự kiện phải được tiêu thụ đúng một lần. JBC EVF,XU_LY vừa kiểm vừa xóa trong một lệnh. RETI không xóa cờ phần mềm."}]);

fillSnips();
